{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;
	var STORAGE_KEY = 'todos-vanillajs';

	// -----------------------------------------------------------------------
	// Store
	// -----------------------------------------------------------------------

	/**
	 * @planks("the app is loaded")
	 * @planks("the app is reloaded")
	 * @planks("localStorage has todos with titles {string} and {string}")
	 */
	function Store(key) {
		this.key = key;
	}

	/**
	 * @planks("the app is loaded")
	 * @planks("the app is reloaded")
	 * @planks("localStorage has todos with titles {string} and {string}")
	 */
	Store.prototype.getTodos = function () {
		var data = localStorage.getItem(this.key);
		return data ? JSON.parse(data) : [];
	};

	/**
	 * @planks("I type {string} into the new-todo input and press Enter")
	 * @planks("I click the toggle checkbox on the {string} todo")
	 * @planks("I click the destroy button on the {string} todo")
	 * @planks("I click the toggle-all checkbox")
	 * @planks("I click the clear-completed button")
	 * @planks("I change the edit input to {string} and blur")
	 * @planks("I change the edit input to {string} and press Enter")
	 */
	Store.prototype.save = function (todos) {
		localStorage.setItem(this.key, JSON.stringify(todos));
	};

	// -----------------------------------------------------------------------
	// App
	// -----------------------------------------------------------------------

	/**
	 * @planks("the app is loaded")
	 * @planks("the app is reloaded")
	 */
	function App() {
		this.store = new Store(STORAGE_KEY);
		this.todos = [];
		this.filter = 'all';
		this.todoList = document.querySelector('.todo-list');
		this.main = document.querySelector('.main');
		this.footer = document.querySelector('.footer');
		this.newTodo = document.querySelector('.new-todo');
		this.toggleAll = document.querySelector('.toggle-all');
		this.todoCount = document.querySelector('.todo-count');
		this.clearCompleted = document.querySelector('.clear-completed');
		this.filters = document.querySelectorAll('.filters a');
	}

	/**
	 * @planks("the app is loaded")
	 * @planks("the app is reloaded")
	 */
	App.prototype.init = function () {
		this.todos = this.store.getTodos();
		this.bindEvents();
		this.setFilterFromHash();
		this.render();
	};

	App.prototype.bindEvents = function () {
		var self = this;

		// New todo
		this.newTodo.addEventListener('keydown', function (e) {
			if (e.keyCode === ENTER_KEY) {
				self.addTodo();
			}
		});

		// Toggle all
		this.toggleAll.addEventListener('change', function () {
			self.toggleAllTodos(this.checked);
		});

		// Clear completed
		this.clearCompleted.addEventListener('click', function () {
			self.clearCompletedTodos();
		});

		// Todo list events (delegation)
		this.todoList.addEventListener('click', function (e) {
			var li = e.target.closest('li');
			if (!li) return;

			if (e.target.classList.contains('toggle')) {
				self.toggleTodo(li.dataset.id);
			}

			if (e.target.classList.contains('destroy')) {
				self.destroyTodo(li.dataset.id);
			}
		});

		// Double-click to edit (delegation)
		this.todoList.addEventListener('dblclick', function (e) {
			var label = e.target.closest('label');
			if (!label) return;
			var li = label.closest('li');
			if (!li) return;
			self.editTodo(li);
		});

		// Edit input events (delegation)
		this.todoList.addEventListener('keydown', function (e) {
			var editInput = e.target.closest('.edit');
			if (!editInput) return;
			var li = editInput.closest('li');
			if (!li) return;

			if (e.keyCode === ENTER_KEY) {
				self.commitEdit(li, editInput.value);
			} else if (e.keyCode === ESCAPE_KEY) {
				self.cancelEdit(li);
			}
		});

		this.todoList.addEventListener('blur', function (e) {
			var editInput = e.target.closest('.edit');
			if (!editInput) return;
			var li = editInput.closest('li');
			if (!li) return;
			// Don't commit if editing was cancelled (e.g., by pressing Escape).
			// cancelEdit removes the 'editing' class before blur can fire.
			if (!li.classList.contains('editing')) return;
			self.commitEdit(li, editInput.value);
		}, true);

		// Routing
		window.addEventListener('hashchange', function () {
			self.setFilterFromHash();
			self.render();
		});
	};

	/**
	 * @planks("I navigate to {string}")
	 * @planks("I navigate to the default route")
	 * @planks("the app is loaded")
	 * @planks("the app is reloaded")
	 */
	App.prototype.setFilterFromHash = function () {
		var hash = window.location.hash;
		if (hash === '#/active') {
			this.filter = 'active';
		} else if (hash === '#/completed') {
			this.filter = 'completed';
		} else {
			this.filter = 'all';
		}
	};

	/**
	 * @planks("I should see {string} in the todo list")
	 * @planks("I should not see {string} in the todo list")
	 */
	App.prototype.getFilteredTodos = function () {
		if (this.filter === 'active') {
			return this.todos.filter(function (t) { return !t.completed; });
		}
		if (this.filter === 'completed') {
			return this.todos.filter(function (t) { return t.completed; });
		}
		return this.todos;
	};

	/**
	 * @planks("I type {string} into the new-todo input and press Enter")
	 * @planks("I type {string} into the new-todo input and press Enter")
	 */
	App.prototype.addTodo = function () {
		var title = this.newTodo.value.trim();
		if (title === '') return;
		var todo = {
			id: Date.now() + Math.random(),
			title: title,
			completed: false
		};
		this.todos.push(todo);
		this.store.save(this.todos);
		this.newTodo.value = '';

		// Surgical DOM update: append just the new li (if it passes the filter)
		if (this.filter !== 'completed') {
			var temp = document.createElement('div');
			temp.innerHTML = this.todoHtml(todo);
			this.todoList.appendChild(temp.firstChild);
		}

		this.updateUI();
	};

	/**
	 * @planks("I click the toggle checkbox on the {string} todo")
	 */
	App.prototype.toggleTodo = function (id) {
		for (var i = 0; i < this.todos.length; i++) {
			if (this.todos[i].id == id) {
				this.todos[i].completed = !this.todos[i].completed;
				break;
			}
		}
		this.store.save(this.todos);

		// Surgical DOM update: toggle just this item's class and checkbox
		// instead of replacing the entire list (which detaches DOM nodes).
		var li = this.todoList.querySelector('li[data-id="' + id + '"]');
		if (li) {
			var todo = this.todos.filter(function (t) { return t.id == id; })[0];
			if (todo) {
				// If the item is hidden by the current filter, remove it from the DOM
				if ((this.filter === 'active' && todo.completed) ||
					(this.filter === 'completed' && !todo.completed)) {
					li.parentNode.removeChild(li);
				} else {
					li.classList.toggle('completed', todo.completed);
					var checkbox = li.querySelector('.toggle');
					if (checkbox) checkbox.checked = todo.completed;
				}
			}
		}

		this.updateUI();
	};

	/**
	 * @planks("I click the destroy button on the {string} todo")
	 * @planks("I change the edit input to {string} and press Enter")
	 * @planks("I change the edit input to {string} and blur")
	 */
	App.prototype.destroyTodo = function (id) {
		this.todos = this.todos.filter(function (t) { return t.id != id; });
		this.store.save(this.todos);

		// Surgical DOM update: remove just this item's li
		var li = this.todoList.querySelector('li[data-id="' + id + '"]');
		if (li) {
			li.parentNode.removeChild(li);
		}

		this.updateUI();
	};

	/**
	 * @planks("I click the toggle-all checkbox")
	 */
	App.prototype.toggleAllTodos = function (checked) {
		for (var i = 0; i < this.todos.length; i++) {
			this.todos[i].completed = checked;
		}
		this.store.save(this.todos);

		// Surgical DOM update: toggle every visible li instead of full re-render.
		// For filtered views, items that no longer match the filter are removed.
		var lis = this.todoList.querySelectorAll('li');
		for (var j = 0; j < lis.length; j++) {
			var li = lis[j];
			var todo = this.todos.filter(function (t) { return t.id == li.dataset.id; })[0];
			if (!todo) continue;

			if ((this.filter === 'active' && todo.completed) ||
				(this.filter === 'completed' && !todo.completed)) {
				li.parentNode.removeChild(li);
				j--; // adjust index after removal
			} else {
				li.classList.toggle('completed', todo.completed);
				var checkbox = li.querySelector('.toggle');
				if (checkbox) checkbox.checked = todo.completed;
			}
		}

		this.updateUI();
	};

	/**
	 * @planks("I click the clear-completed button")
	 */
	App.prototype.clearCompletedTodos = function () {
		this.todos = this.todos.filter(function (t) { return !t.completed; });
		this.store.save(this.todos);

		// Surgical DOM update: remove completed li elements
		var lis = this.todoList.querySelectorAll('li.completed');
		for (var i = 0; i < lis.length; i++) {
			lis[i].parentNode.removeChild(lis[i]);
			i--;
		}

		this.updateUI();
	};

	/**
	 * @planks("I double-click the label of {string}")
	 */
	App.prototype.editTodo = function (li) {
		li.classList.add('editing');
		var editInput = li.querySelector('.edit');
		editInput.value = li.querySelector('label').textContent;
		editInput.focus();
		// Set cursor at end
		editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
	};

	/**
	 * @planks("I change the edit input to {string} and blur")
	 * @planks("I change the edit input to {string} and press Enter")
	 */
	App.prototype.commitEdit = function (li, value) {
		var title = value.trim();
		var id = li.dataset.id;

		if (title === '') {
			this.destroyTodo(id);
			return;
		}

		for (var i = 0; i < this.todos.length; i++) {
			if (this.todos[i].id == id) {
				this.todos[i].title = title;
				break;
			}
		}
		this.store.save(this.todos);
		li.classList.remove('editing');

		// Surgical DOM update: update just the label text and edit input value
		var label = li.querySelector('label');
		if (label) label.textContent = title;
		var editInput = li.querySelector('.edit');
		if (editInput) editInput.value = title;

		this.updateUI();
	};

	/**
	 * @planks("I change the edit input to {string} and press Escape")
	 */
	App.prototype.cancelEdit = function (li) {
		li.classList.remove('editing');
	};

	// -----------------------------------------------------------------------
	// Render
	// -----------------------------------------------------------------------

	/**
	 * Update all UI state except the todo list (count, visibility, filters,
	 * toggle-all, clear-completed). Extracted so individual mutations can
	 * surgically update the list without a full innerHTML replacement, which
	 * detaches DOM nodes and breaks browser-based test chains (Cypress).
	 */
	App.prototype.updateUI = function () {
		// Main and footer visibility
		var hasTodos = this.todos.length > 0;
		this.main.style.display = hasTodos ? 'block' : 'none';
		this.footer.style.display = hasTodos ? 'block' : 'none';

		// Toggle-all checkbox state
		var allCompleted = this.todos.length > 0 && this.todos.every(function (t) { return t.completed; });
		this.toggleAll.checked = allCompleted;

		// Clear completed visibility
		var hasCompleted = this.todos.some(function (t) { return t.completed; });
		this.clearCompleted.style.display = hasCompleted ? 'block' : 'none';

		// Update count
		var activeCount = this.todos.filter(function (t) { return !t.completed; }).length;
		var itemWord = activeCount === 1 ? 'item' : 'items';
		this.todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemWord + ' left';

		// Update filter links
		for (var j = 0; j < this.filters.length; j++) {
			var a = this.filters[j];
			var href = a.getAttribute('href');
			if (href === '#/') {
				a.classList.toggle('selected', this.filter === 'all');
			} else if (href === '#/active') {
				a.classList.toggle('selected', this.filter === 'active');
			} else if (href === '#/completed') {
				a.classList.toggle('selected', this.filter === 'completed');
			}
		}
	};

	/**
	 * Build the HTML string for a single todo <li>.
	 */
	App.prototype.todoHtml = function (todo) {
		var completedClass = todo.completed ? ' class="completed"' : '';
		var checked = todo.completed ? ' checked' : '';
		var html = '<li' + completedClass + ' data-id="' + todo.id + '">';
		html += '<div class="view">';
		html += '<input class="toggle" type="checkbox"' + checked + '>';
		html += '<label>' + this.escapeHtml(todo.title) + '</label>';
		html += '<button class="destroy"></button>';
		html += '</div>';
		html += '<input class="edit" value="' + this.escapeHtml(todo.title) + '">';
		html += '</li>';
		return html;
	};

	/**
	 * Full render: replaces the entire todo-list innerHTML. Used for initial
	 * load, reload, and route changes. Individual mutations (toggle, destroy,
	 * add, clear-completed, commitEdit) use surgical DOM updates instead.
	 *
	 * @planks("I should see {string} in the todo list")
	 * @planks("I should not see {string} in the todo list")
	 * @planks("the todo list should be empty")
	 * @planks("the {string} todo should have the completed class")
	 * @planks("the {string} todo should not have the completed class")
	 * @planks("the todo should be in editing mode")
	 * @planks("all todos should be completed")
	 * @planks("no todos should be completed")
	 * @planks("the toggle-all checkbox should be checked")
	 * @planks("the clear-completed button should be hidden")
	 * @planks("the todo-count should show {string}")
	 * @planks("the main section should be hidden")
	 * @planks("the footer section should be hidden")
	 * @planks("the main section should be visible")
	 * @planks("the footer section should be visible")
	 * @planks("the {string} filter link should have the selected class")
	 * @planks("the {string} todo should not be in editing mode")
	 */
	App.prototype.render = function () {
		var filtered = this.getFilteredTodos();
		var html = '';

		for (var i = 0; i < filtered.length; i++) {
			html += this.todoHtml(filtered[i]);
		}

		this.todoList.innerHTML = html;
		this.updateUI();
	};

	App.prototype.escapeHtml = function (str) {
		var div = document.createElement('div');
		div.appendChild(document.createTextNode(str));
		return div.innerHTML;
	};

	// -----------------------------------------------------------------------
	// Bootstrap
	// -----------------------------------------------------------------------

	var app = new App();

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', function () { app.init(); });
	} else {
		app.init();
	}
})();

const { Given, When, Then, After } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ============================================================
// Helpers
// ============================================================

function getDoc() {
  return this.document;
}

function getWindow() {
  return this.window;
}

function query(selector) {
  return this.document.querySelector(selector);
}

function queryAll(selector) {
  return this.document.querySelectorAll(selector);
}

function findTodoItem(label) {
  const items = queryAll.call(this, '.todo-list li');
  for (const li of items) {
    const lbl = li.querySelector('label');
    if (lbl && lbl.textContent.trim() === label) return li;
  }
  return null;
}

function pressKey(el, key, keyCode) {
  const evt = new this.window.KeyboardEvent('keydown', { key, keyCode, which: keyCode, bubbles: true });
  el.dispatchEvent(evt);
}

function createTodoViaUI(text) {
  const input = query.call(this, '.new-todo');
  if (!input) throw new Error('new-todo input not found');
  input.value = text;
  pressKey.call(this, input, 'Enter', 13);
}

function completeTodoViaUI(label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Todo "${label}" not found`);
  const toggle = li.querySelector('.toggle');
  if (!toggle) throw new Error(`Toggle checkbox not found for "${label}"`);
  toggle.click();
}

// ============================================================
// Given
// ============================================================

Given('the app is loaded', function () {
  // Already loaded by Before hook in world.js
  const main = query.call(this, '.main');
  assert.ok(main, 'App should be loaded');
});

Given('there is a todo {string}', function (title) {
  createTodoViaUI.call(this, title);
  const li = findTodoItem.call(this, title);
  assert.ok(li, `Todo "${title}" should exist`);
});

Given('there are todos {string} and {string}', function (title1, title2) {
  createTodoViaUI.call(this, title1);
  createTodoViaUI.call(this, title2);
  assert.ok(findTodoItem.call(this, title1), `Todo "${title1}" should exist`);
  assert.ok(findTodoItem.call(this, title2), `Todo "${title2}" should exist`);
});

Given('there is a completed todo {string}', function (title) {
  createTodoViaUI.call(this, title);
  completeTodoViaUI.call(this, title);
  const li = findTodoItem.call(this, title);
  assert.ok(li, `Todo "${title}" should exist`);
  assert.ok(li.classList.contains('completed'), `Todo "${title}" should be completed`);
});

Given('there are completed todos {string} and {string}', function (title1, title2) {
  createTodoViaUI.call(this, title1);
  createTodoViaUI.call(this, title2);
  completeTodoViaUI.call(this, title1);
  completeTodoViaUI.call(this, title2);
  assert.ok(findTodoItem.call(this, title1).classList.contains('completed'));
  assert.ok(findTodoItem.call(this, title2).classList.contains('completed'));
});

Given('there are completed todos {string} and active todos {string}', function (completed, active) {
  createTodoViaUI.call(this, completed);
  createTodoViaUI.call(this, active);
  completeTodoViaUI.call(this, completed);
  assert.ok(findTodoItem.call(this, completed).classList.contains('completed'));
  assert.ok(!findTodoItem.call(this, active).classList.contains('completed'));
});

Given('there are no todos', function () {
  const items = queryAll.call(this, '.todo-list li');
  assert.strictEqual(items.length, 0, 'There should be no todos');
});

Given('localStorage has todos with titles {string} and {string}', function (title1, title2) {
  const todos = [
    { id: '1', title: title1, completed: false },
    { id: '2', title: title2, completed: false }
  ];
  this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));
});

// ============================================================
// When
// ============================================================

When('I type {string} into the new-todo input and press Enter', function (text) {
  createTodoViaUI.call(this, text);
});

When('I click the toggle checkbox on the {string} todo', function (label) {
  completeTodoViaUI.call(this, label);
});

When('I click the destroy button on the {string} todo', function (label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Todo "${label}" not found`);
  const destroy = li.querySelector('.destroy');
  if (!destroy) throw new Error(`Destroy button not found for "${label}"`);
  destroy.click();
});

When('I double-click the label of {string}', function (label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Todo "${label}" not found`);
  const labelEl = li.querySelector('label');
  if (!labelEl) throw new Error(`Label not found for "${label}"`);
  const dblClick = new this.window.MouseEvent('dblclick', { bubbles: true });
  labelEl.dispatchEvent(dblClick);
});

When('I change the edit input to {string} and blur', function (newText) {
  const editInput = query.call(this, '.todo-list li.editing .edit');
  if (!editInput) throw new Error('No todo in editing mode');
  editInput.value = newText;
  const blurEvent = new this.window.Event('blur', { bubbles: true });
  editInput.dispatchEvent(blurEvent);
});

When('I change the edit input to {string} and press Enter', function (newText) {
  const editInput = query.call(this, '.todo-list li.editing .edit');
  if (!editInput) throw new Error('No todo in editing mode');
  editInput.value = newText;
  pressKey.call(this, editInput, 'Enter', 13);
});

When('I change the edit input to {string} and press Escape', function (newText) {
  const editInput = query.call(this, '.todo-list li.editing .edit');
  if (!editInput) throw new Error('No todo in editing mode');
  editInput.value = newText;
  pressKey.call(this, editInput, 'Escape', 27);
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = query.call(this, '.toggle-all');
  if (!toggleAll) throw new Error('toggle-all checkbox not found');
  toggleAll.click();
});

When('I click the clear-completed button', function () {
  const btn = query.call(this, '.clear-completed');
  if (!btn) throw new Error('clear-completed button not found');
  btn.click();
});

When('I view the app', function () {
  // App is already loaded, this is a no-op for the step
});

When('I complete the todo {string}', function (label) {
  completeTodoViaUI.call(this, label);
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('I navigate to the default route', function () {
  this.navigate('#/');
});

When('the app is reloaded', function () {
  // Preserve localStorage data and hash across Window recreation
  const savedData = {};
  for (var i = 0; i < this.window.localStorage.length; i++) {
    var key = this.window.localStorage.key(i);
    savedData[key] = this.window.localStorage.getItem(key);
  }
  const savedHash = this.window.location.hash;
  return this.disposeApp().then(() => {
    // Create a fresh window first, restore data, THEN load the app
    // so the app initializes with data already in localStorage
    const fs = require('node:fs');
    const path = require('node:path');
    const ROOT = path.resolve(__dirname, '..', '..');
    const { Window } = require('happy-dom');

    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // Restore saved data BEFORE loading the app
    for (var k in savedData) {
      this.window.localStorage.setItem(k, savedData[k]);
    }

    // Now load the app
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    const appSource = fs.readFileSync(appPath, 'utf8');
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // Restore the click-handler routing shim from world.js
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);

